function transition(state, event) {
  if (event.type === "SAVE" && (state.status === "idle" || state.status === "error"))
    return { status: "saving", draft: event.draft };
  if (event.type === "SAVED" && state.status === "saving")
    return { status: "saved", draft: state.draft };
  if (event.type === "FAILED" && state.status === "saving")
    return { status: "error", draft: state.draft, message: event.message };
  if (event.type === "RESET" && state.status !== "saving") return { status: "idle" };
  return state;
}

